// EDIT THIS LINE: the Telegram chat id that should receive failure alerts.
// Currently Edgar's. Alix should replace it with her own when she takes the bot over.
const ADMIN_CHAT_ID = '7550718257';

const j = $input.first().json || {};
const ex = j.execution || {};
const wf = j.workflow || {};
const err = ex.error || {};

const lines = [];
lines.push('Interview coach failed');
lines.push('');
lines.push('Workflow: ' + (wf.name || 'unknown'));
lines.push('Node: ' + (ex.lastNodeExecuted || 'unknown'));
lines.push('Mode: ' + (ex.mode || 'unknown'));
lines.push('');
lines.push('Error: ' + String(err.message || 'no message').slice(0, 500));

if (ex.url) {
  lines.push('');
  lines.push(ex.url);
}

if (!ADMIN_CHAT_ID) {
  // No admin id set, so there is nobody to tell. Fail quietly rather than erroring inside the error handler.
  return [];
}

return [{ json: { chat_id: ADMIN_CHAT_ID, reply: lines.join('\n') } }];
